import { toolbarAnchorSelector } from './toolbarReview';

const maxSelectorLength = 1024;
const maxAlternatives = 3;
// Identity/semantic attributes only. State such as data-state, aria-expanded and open changes on close.
const stableAttributes = ['data-testid', 'data-test-id', 'data-test', 'data-cy', 'data-qa', 'data-anchor', 'data-id', 'data-key', 'data-slot', 'data-component', 'aria-label', 'role'];

/** React useId and the ids generated by common layer libraries are local to one render. */
function stableValue(value: string) {
    return value.length > 0 && value.length <= 160 && !/[\u0000-\u001f\u007f]/.test(value)
        && !/(?:_[rR]_[\da-z]+_|[«:][rR][\da-z]+[»:])/i.test(value)
        && !/^(?:base-ui|radix|headlessui|react-aria|reach|mui)-/i.test(value);
}

/** Quoted CSS attribute values, without control characters or unescaped list separators. */
function attributeValue(value: string) {
    return value.replace(/["\\,]/g, character => `\\${character}`);
}

function semanticSegments(element: Element) {
    const tag = element.tagName.toLowerCase();
    const segments: string[] = [];
    // Keep CSS.escape's simple identifier form within the API grammar (a leading digit needs a hex escape).
    if (stableValue(element.id) && /^(?:[A-Za-z_]|--[A-Za-z_]|-[A-Za-z_])/.test(element.id)) {
        segments.push(`#${CSS.escape(element.id).replace(/[^\x00-\x7f]/gu, character => `\\${character}`)}`);
    }
    for (const name of stableAttributes) {
        const value = element.getAttribute(name);
        if (value && stableValue(value)) segments.push(`${tag}[${name}="${attributeValue(value)}"]`);
    }
    const role = element.getAttribute('role');
    const label = element.getAttribute('aria-label');
    if (role && label && stableValue(role) && stableValue(label)) {
        segments.unshift(`${tag}[role="${attributeValue(role)}"][aria-label="${attributeValue(label)}"]`);
    }
    return segments;
}

/** A few independently unique selectors in the existing comma-list format, within the API limit. */
export function anchorSelector(element: Element | null | undefined): string {
    if (!element) return '';
    const toolbar = toolbarAnchorSelector(element);
    if (toolbar) return toolbar;

    const alternatives: string[] = [];
    const add = (candidate: string) => {
        if (alternatives.includes(candidate) || alternatives.length >= maxAlternatives
            || [...alternatives, candidate].join(',').length > maxSelectorLength) return;
        try {
            const matches = document.querySelectorAll(candidate);
            if (matches.length === 1 && matches[0] === element) alternatives.push(candidate);
        } catch { /* Try another supported selector. */ }
    };
    const path: string[] = [];
    let structural = '';
    for (let node: Element | null = element; node && path.join('>').length <= maxSelectorLength; node = node.parentElement) {
        for (const segment of semanticSegments(node)) add([segment, ...path].join('>'));
        if (alternatives.length >= maxAlternatives) break;
        const siblings: Element[] = node.parentElement ? [...node.parentElement.children].filter(other => other.tagName === node!.tagName) : [node];
        path.unshift(`${node.tagName.toLowerCase()}${siblings.length > 1 ? `:nth-of-type(${siblings.indexOf(node) + 1})` : ''}`);
        if (!structural) {
            const candidate = path.join('>');
            const matches = document.querySelectorAll(candidate);
            if (matches.length === 1 && matches[0] === element) structural = candidate;
        }
    }
    // Do not mix an unscoped positional fallback with semantic identities: after a portal moves,
    // that path could name unrelated content and make an otherwise exact anchor ambiguous.
    if (!alternatives.length && structural) add(structural);
    return alternatives.join(',');
}
